// Builds the request for the Anthropic Messages API from the form input.
const topic = $json['Topic'];
const minutes = Number($json['Video length (minutes)'] || 8);
const language = $json['Language'] || 'English';
const words = Math.round(minutes * 150); // ~150 spoken words per minute

return [{ json: { topic, body: {
  model: 'claude-sonnet-5-5',
  max_tokens: 8000,
  system: "You are a scriptwriter for faceless YouTube channels. Write a complete, spoken-word video script. Use these sections, each starting with a line '## SECTION NAME': HOOK, SETUP, FACTS, THEORIES, ENDING. No stage directions, no emojis, no markdown except the section headers. After the script add a line '## TITLES' with 5 title ideas, one per line.",
  messages: [{ role: 'user', content:
    `Topic: ${topic}\nLanguage: ${language}\nTarget length: about ${words} words (${minutes} minutes).` }]
} } }];

// Extracts the script text and counts words.
const text = ($json.content || []).filter(c => c.type === 'text').map(c => c.text).join('\n');
const words = text.split(/\s+/).filter(Boolean).length;
return [{ json: { script: text, words, minutes: Math.round(words / 150) } }];
